* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: #f5f7fa;
  color: #1f2933;
}

.app {
  max-width: 1500px;
  margin: 0 auto;
  padding: 20px;
}

.app-header h1 {
  margin: 0 0 6px 0;
  font-size: 24px;
  font-weight: 600;
  color: #102a43;
}

.subtitle {
  margin: 0 0 18px 0;
  color: #486581;
  font-size: 13px;
}

.app-main {
  display: flex;
  gap: 24px;
  align-items: flex-start;
  flex-wrap: wrap;
}

.chart-pane,
.table-pane {
  background: #ffffff;
  border-radius: 10px;
  box-shadow: 0 1px 3px rgba(16, 42, 67, 0.08), 0 1px 2px rgba(16, 42, 67, 0.04);
  padding: 18px;
}

.chart-pane {
  flex: 1 1 900px;
  min-width: 760px;
}

.table-pane {
  flex: 0 0 520px;
  min-width: 420px;
}

.pane-title {
  margin: 0 0 12px 0;
  font-size: 16px;
  font-weight: 600;
  color: #102a43;
}

#chart-container {
  width: 100%;
  height: 640px;
  position: relative;
  background: linear-gradient(180deg, #fbfdff 0%, #f1f5f9 100%);
  border-radius: 8px;
  overflow: hidden;
}

#chart-container svg {
  width: 100%;
  height: 100%;
  display: block;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 16px;
  margin-top: 12px;
  font-size: 12px;
  color: #334e68;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  background: #f0f4f8;
  border-radius: 4px;
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 1px solid rgba(0,0,0,0.1);
}

.bubble {
  cursor: pointer;
  transition: stroke-width 0.15s ease;
}

.bubble.is-etf {
  cursor: default;
}

.bubble:hover {
  stroke-width: 3px;
}

.bubble.selected {
  stroke: #102a43;
  stroke-width: 3px;
}

.bubble-label {
  pointer-events: none;
  user-select: none;
  font-size: 10px;
  font-weight: 600;
  fill: #ffffff;
  text-anchor: middle;
  dominant-baseline: middle;
  paint-order: stroke;
  stroke: rgba(0,0,0,0.25);
  stroke-width: 2px;
  stroke-linejoin: round;
}

.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(16, 42, 67, 0.95);
  color: #fff;
  padding: 8px 10px;
  border-radius: 6px;
  font-size: 12px;
  line-height: 1.4;
  max-width: 240px;
  opacity: 0;
  transform: translate(-50%, -110%);
  transition: opacity 0.12s ease;
  box-shadow: 0 4px 10px rgba(0,0,0,0.2);
  z-index: 10;
}

.tooltip.visible { opacity: 1; }

.tooltip .ticker {
  font-weight: 700;
  font-size: 13px;
  margin-bottom: 4px;
}

.tooltip .name {
  color: #cbd2d9;
  margin-bottom: 4px;
}

.tooltip .sector-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #9fb3c8;
}

.table-controls {
  display: flex;
  gap: 8px;
  margin-bottom: 10px;
  align-items: center;
  font-size: 12px;
  color: #486581;
}

.table-controls select,
.table-controls input {
  padding: 6px 8px;
  border: 1px solid #cbd2d9;
  border-radius: 4px;
  font-size: 13px;
  background: #fff;
  color: #1f2933;
}

.table-controls input { flex: 1; }

.table-scroll {
  max-height: 580px;
  overflow-y: auto;
  border: 1px solid #e4e7eb;
  border-radius: 6px;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

#stock-table thead {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #f0f4f8;
}

#stock-table th {
  text-align: left;
  padding: 8px 10px;
  font-weight: 600;
  color: #243b53;
  border-bottom: 1px solid #cbd2d9;
  cursor: pointer;
  user-select: none;
}

#stock-table th.num { text-align: right; }
#stock-table th.sort-asc::after { content: " ▲"; font-size: 10px; }
#stock-table th.sort-desc::after { content: " ▼"; font-size: 10px; }

#stock-table td {
  padding: 7px 10px;
  border-bottom: 1px solid #f0f4f8;
  color: #334e68;
}

#stock-table td.num { text-align: right; font-variant-numeric: tabular-nums; }

#stock-table tbody tr {
  cursor: pointer;
  transition: background 0.12s ease;
}

#stock-table tbody tr:hover {
  background: #f0f7ff;
}

#stock-table tbody tr.selected {
  background: #d9e8ff !important;
  font-weight: 600;
}

#stock-table tbody tr.hidden { display: none; }

.sector-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  margin-right: 6px;
  vertical-align: middle;
  border: 1px solid rgba(0,0,0,0.1);
}

(function () {
  "use strict";

  const DATA_URL = "data/stock-descriptions.csv";

  const width = 880;
  const height = 640;

  const ETF_UNIFORM_RADIUS = 16;

  const formatMarketCap = (v) => {
    if (v == null || isNaN(v)) return "—";
    const abs = Math.abs(v);
    if (abs >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (abs >= 1e9) return (v / 1e9).toFixed(2) + "B";
    if (abs >= 1e6) return (v / 1e6).toFixed(2) + "M";
    if (abs >= 1e3) return (v / 1e3).toFixed(2) + "K";
    return String(v);
  };

  d3.csv(DATA_URL).then((raw) => {
    const rows = raw.map((d) => {
      const mc = d.marketCap && d.marketCap.trim() !== "" ? +d.marketCap : null;
      return {
        ticker: d.ticker,
        name: d["full name"],
        sector: d.sector,
        marketCap: mc,
        country: d.country,
        website: d.website,
        longBusinessSummary: d.longBusinessSummary,
        isETF: d.sector === "ETF",
      };
    });

    const sectors = Array.from(new Set(rows.map((r) => r.sector)));
    sectors.sort((a, b) => {
      if (a === "ETF") return 1;
      if (b === "ETF") return -1;
      return a.localeCompare(b);
    });

    const sectorColor = d3.scaleOrdinal()
      .domain(sectors)
      .range(d3.schemeCategory10.concat(["#7f5af0", "#2cb1bc"]).slice(0, sectors.length));

    const marketCaps = rows.filter((r) => !r.isETF && r.marketCap != null).map((r) => r.marketCap);
    const rMin = 8;
    const rMax = 38;
    let rScale = d3.scaleSqrt()
      .domain([d3.min(marketCaps), d3.max(marketCaps)])
      .range([rMin, rMax]);
    if (!isFinite(rMin) || !isFinite(rMax) || rMin === rMax) {
      rScale = () => (rMin + rMax) / 2;
    }

    const radiusOf = (d) => (d.isETF ? ETF_UNIFORM_RADIUS : rScale(d.marketCap));

    const clusterCenters = computeClusterCenters(sectors, width, height);
    rows.forEach((d) => {
      d.color = sectorColor(d.sector);
      d.radius = radiusOf(d);
      d.cx = clusterCenters[d.sector].x;
      d.cy = clusterCenters[d.sector].y;
    });

    const svg = d3.select("#chart-container")
      .append("svg")
      .attr("viewBox", `0 0 ${width} ${height}`)
      .attr("preserveAspectRatio", "xMidYMid meet");

    const defs = svg.append("defs");
    defs.append("filter")
      .attr("id", "soft-shadow")
      .attr("x", "-50%").attr("y", "-50%")
      .attr("width", "200%").attr("height", "200%")
      .html('<feGaussianBlur in="SourceAlpha" stdDeviation="1.4"/><feOffset dx="0" dy="1" result="offsetblur"/><feComponentTransfer><feFuncA type="linear" slope="0.35"/></feComponentTransfer><feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge>');

    const tooltip = d3.select("#tooltip");

    const sim = d3.forceSimulation(rows)
      .force("x", d3.forceX((d) => d.cx).strength(0.18))
      .force("y", d3.forceY((d) => d.cy).strength(0.18))
      .force("collide", d3.forceCollide((d) => d.radius + 1.5))
      .force("charge", d3.forceManyBody().strength(-6))
      .force("center", d3.forceCenter(width / 2, height / 2).strength(0.04));

    const groups = svg.selectAll("g.bubble-group")
      .data(rows, (d) => d.ticker)
      .enter()
      .append("g")
      .attr("class", "bubble-group")
      .attr("data-ticker", (d) => d.ticker);

    groups.append("circle")
      .attr("class", (d) => "bubble" + (d.isETF ? " is-etf" : ""))
      .attr("r", (d) => d.radius)
      .attr("fill", (d) => d.color)
      .attr("fill-opacity", 0.85)
      .attr("stroke", "#ffffff")
      .attr("stroke-width", 1.5)
      .attr("filter", "url(#soft-shadow)")
      .on("mouseover", function (event, d) {
        if (d.isETF) return;
        tooltip
          .classed("visible", true)
          .html(
            `<div class="ticker">${escapeHTML(d.ticker)}</div>` +
            `<div class="name">${escapeHTML(d.name)}</div>` +
            `<div class="sector-label">${escapeHTML(d.sector)}</div>`
          );
        const containerRect = document.getElementById("chart-container").getBoundingClientRect();
        const x = event.clientX - containerRect.left;
        const y = event.clientY - containerRect.top;
        tooltip.style("left", x + "px").style("top", y + "px");
      })
      .on("mousemove", function (event, d) {
        if (d.isETF) return;
        const containerRect = document.getElementById("chart-container").getBoundingClientRect();
        const x = event.clientX - containerRect.left;
        const y = event.clientY - containerRect.top;
        tooltip.style("left", x + "px").style("top", y + "px");
      })
      .on("mouseout", function () {
        tooltip.classed("visible", false);
      })
      .on("click", function (event, d) {
        event.stopPropagation();
        selectTicker(d.ticker);
      });

    groups.append("text")
      .attr("class", "bubble-label")
      .attr("dy", "0.35em")
      .text((d) => d.ticker);

    sim.on("tick", () => {
      groups.attr("transform", (d) => {
        const x = Math.max(d.radius, Math.min(width - d.radius, d.x));
        const y = Math.max(d.radius, Math.min(height - d.radius, d.y));
        return `translate(${x},${y})`;
      });
    });

    drawLegend(sectors, sectorColor);

    const sortKey = { key: "marketCap", dir: "desc" };
    let currentFilter = "All";

    function renderTable() {
      let view = rows.slice();
      if (currentFilter !== "All") view = view.filter((r) => r.sector === currentFilter);
      const q = (document.getElementById("search-input").value || "").trim().toLowerCase();
      if (q) {
        view = view.filter((r) =>
          r.ticker.toLowerCase().includes(q) ||
          r.name.toLowerCase().includes(q)
        );
      }
      view.sort(comparator(sortKey));
      const tbody = d3.select("#stock-table tbody");
      const tr = tbody.selectAll("tr").data(view, (d) => d.ticker);
      const trEnter = tr.enter().append("tr").attr("data-ticker", (d) => d.ticker);
      trEnter.append("td").attr("class", "cell-ticker");
      trEnter.append("td").attr("class", "cell-name");
      trEnter.append("td").attr("class", "cell-sector");
      trEnter.append("td").attr("class", "cell-cap num");
      const merged = trEnter.merge(tr);
      merged.select(".cell-ticker").text((d) => d.ticker);
      merged.select(".cell-name").text((d) => d.name);
      merged.select(".cell-sector").html((d) =>
        `<span class="sector-dot" style="background:${d.color}"></span>${escapeHTML(d.sector)}`
      );
      merged.select(".cell-cap").text((d) => formatMarketCap(d.marketCap));
      merged
        .on("click", function (event, d) {
          event.stopPropagation();
          selectTicker(d.ticker);
        })
        .classed("selected", (d) => d.ticker === state.selectedTicker);
      tr.exit().remove();
    }

    function comparator(sortKey) {
      const { key, dir } = sortKey;
      const mul = dir === "asc" ? 1 : -1;
      return (a, b) => {
        let av = a[key];
        let bv = b[key];
        if (key === "marketCap") {
          av = av == null ? -Infinity : av;
          bv = bv == null ? -Infinity : bv;
        }
        if (typeof av === "string") av = av.toLowerCase();
        if (typeof bv === "string") bv = bv.toLowerCase();
        if (av < bv) return -1 * mul;
        if (av > bv) return 1 * mul;
        return 0;
      };
    }

    const state = { selectedTicker: null };

    function selectTicker(ticker) {
      state.selectedTicker = ticker;
      groups.select("circle.bubble").classed("selected", (d) => d.ticker === ticker);
      d3.selectAll("#stock-table tbody tr").classed("selected", function () {
        return this.getAttribute("data-ticker") === ticker;
      });
    }

    d3.selectAll("#stock-table thead th").on("click", function () {
      const key = this.getAttribute("data-sort");
      if (!key) return;
      if (sortKey.key === key) sortKey.dir = sortKey.dir === "asc" ? "desc" : "asc";
      else {
        sortKey.key = key;
        sortKey.dir = key === "marketCap" ? "desc" : "asc";
      }
      d3.selectAll("#stock-table thead th").classed("sort-asc", false).classed("sort-desc", false);
      d3.select(this).classed(sortKey.dir === "asc" ? "sort-asc" : "sort-desc", true);
      renderTable();
    });

    const filterSelect = document.getElementById("filter-select");
    sectors.forEach((s) => {
      const opt = document.createElement("option");
      opt.value = s;
      opt.textContent = s;
      filterSelect.appendChild(opt);
    });
    filterSelect.addEventListener("change", (e) => {
      currentFilter = e.target.value;
      renderTable();
    });
    document.getElementById("search-input").addEventListener("input", () => renderTable());

    svg.on("click", () => {
      state.selectedTicker = null;
      groups.select("circle.bubble").classed("selected", false);
      d3.selectAll("#stock-table tbody tr").classed("selected", false);
    });

    renderTable();

    function drawLegend(sectors, colorScale) {
      const legend = d3.select("#legend");
      legend.selectAll(".legend-item").remove();
      const items = legend.selectAll(".legend-item")
        .data(sectors)
        .enter()
        .append("div")
        .attr("class", "legend-item");
      items.append("span")
        .attr("class", "legend-swatch")
        .style("background", (d) => colorScale(d));
      items.append("span").text((d) => d);
    }

    function computeClusterCenters(sectors, w, h) {
      const n = sectors.length;
      const cols = Math.ceil(Math.sqrt(n));
      const rows = Math.ceil(n / cols);
      const padX = 130;
      const padY = 110;
      const stepX = (w - 2 * padX) / Math.max(1, cols - 1);
      const stepY = (h - 2 * padY) / Math.max(1, rows - 1);
      const centers = {};
      sectors.forEach((s, i) => {
        const c = i % cols;
        const r = Math.floor(i / cols);
        centers[s] = {
          x: cols === 1 ? w / 2 : padX + c * stepX,
          y: rows === 1 ? h / 2 : padY + r * stepY,
        };
      });
      return centers;
    }

    function escapeHTML(s) {
      return String(s == null ? "" : s)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    }
  }).catch((err) => {
    console.error("Failed to load data:", err);
    d3.select("#chart-container").append("div")
      .style("padding", "20px")
      .style("color", "#b00020")
      .text("Failed to load data/stock-descriptions.csv: " + err.message);
  });
})();

